DIRS=[(-1,-1),(-1,1),(1,-1),(1,1)]
def f(inp, fill=3):
    H=len(inp); W=len(inp[0])
    cnt={}
    for r in inp:
        for x in r: cnt[x]=cnt.get(x,0)+1
    bg=max(cnt,key=lambda k:cnt[k])
    out=[[bg]*W for _ in range(H)]
    def is_obs(v): return v!=bg and v!=fill
    for sr in range(H):
        for sc in range(W):
            if inp[sr][sc]==6:
                for didx in range(4):
                    dr,dc=DIRS[didx]; path=[]; r,c=sr,sc
                    while True:
                        rr,cc=r+dr,c+dc
                        if not (0<=rr<H and 0<=cc<W): break
                        if inp[rr][cc]==6: continue   # pass through other seeds
                        if is_obs(inp[rr][cc]): break
                        r,c=rr,cc; path.append((rr,cc))
                    if not path: continue
                    term=inp[r][c] if 0<=r<H and 0<=c<W else None
                    if term==None or term==6: continue  # OOB death / no paint -> drop
                    # ray died at obs after painting >=1: pivot CW from last painted cell
                    new_dr,new_dc=rotate_CW(dr,dc); rr,cc=r,c
                    while True:
                        nrr,ncc=rr+new_dr,cc+new_dc
                        if not (0<=nrr<H and 0<=ncc<W): break
                        if inp[nrr][ncc]==6: break
                        if is_obs(inp[nrr][ncc]): break
                        out[nrr][ncc]=fill; rr,cc=nrr,ncc
    return out

