            except IndexError: pass
            else:
                if OUT[nr][nc]==bg:
                    OUT[nr][nc]=3; r,c=nr,nc; continue
                if OUT[nr][nc]==emc:
                    r,c=nr,nc; continue
            break
            nr,nc=r+dr,c+dk
        # hit something at (nr,nc)
        if OUT[nr][nc]==obs: dk=-dk
        r,c=n+..., ...
        # simplify: loop properly below
    # redo cleanly
    OUT=[row[:] for row in g]
    for er,ec in egs:
        rr,cc=er,ec
        dr,dk=1,-1
        while 0<=rr+dr<H and 0<=cc+dk<W:
            nnr,ncc=rr+dr,cc+dk
            if OUT[nnr][ncc]==bg:
                OUT[nnr][ncc]=3; rr,cc=nnr,ncc
                continue
            elif OUT[nnr][ncc]==emc or OUT[nnr][ncc]==obs:
                break
            elif OUT[nnr][ncc] not in (bg,emc,obs):
                break
        # reflection after hitting obs: reflect horizontally once
        return None
# implement reflection explicitly per step like trace: move one step; if obstacle, reflect, take that step only
OUT=[row[:] for row in g]
for er,ec in egs:
    rr,cc=er,ec
    dr,dk=1,-1
    while 0<=rr+dr<H and 0<=cc+dk<W:
        nnr,ncc=rr+dr,cc+dk
        cell=OUT[nnr][ncc]
        if cell==bg:
            OUT[nnr][ncc]=3; rr,cc=nnr,ncc
        elif cell==emc:
            pass  # skip emitter, but keep moving
        elif cell==obs:
            dk=-dk
        else:
            break
    # after hitting obstacle, one more step with reflected direction? in demo the ray stopped AT the bounce (8,13 painted though)
# fix: emulate the physical trace from demo: ray at (7,12) heading down-left; next would be (8,11)=obs; instead (8,13) painted.
# so when next cell is obs, reflect and then take the reflected step (if inside).
def apply():
    OUT=[row[:] for row in g]
    for er,ec in egs:
        rr,cc=er,ec; dr,dk=1,-1
        while 0<=rr+dr<H and 0<=cc+dk<W:
            nnr,ncc=rr+dr,cc+dk
            cell=OUT[nnr][ncc]
            if cell==bg:
                OUT[nnr][ncc]=3; rr,cc=nnr,ncc; dr,dk=1,-1
            elif cell==emc:
                pass
            elif cell==obs:
                dk=-dk; rr,cc=nnr,ncc
            else:
                break
    return OUT
