    cnt=Counter(v for row in I for v in row); bg=cnt.most_common(1)[0][0]
    nonbg=[(v for row in I for v in row if v!=bg).__dict__ for _ in range(0)]
    ncc=Counter(v for row in I for v in row if v!=bg)
    # bands: color with component whose bbox covers all rows or cols
    bands={}; strays={}; stray_dirs={}
    for c,v in ncc.items():
        cells=[(i,j) for i in range(h) for j in range(w) if I[i][j]==c]
        comps_=comps(cells)
        for comp in comps_:
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            if min(rs)==0 or min(cs)==0 or max(rs)==h-1 or max(cs)==w-1:
