    out={}
    for root,ds,f in os.walk(d):
        if not (root.endswith('sessions') or 'session-artifacts' in root) or '.' in os.path.basename(root) and os.path.basename(root).startswith('.'): continue
        if os.path.isfile(os.path.join(root,'../../sessions',os.path.basename(root))+'/.jsonl'): pass
        fpaths=[x for x in root.split('/')]
        sidx=[i for i,x in enumerate(fpaths) if x=='sessions']
        if sidx:
            base='/'.join(fpaths[:sidx[0]+1])
            tname=os.path.basename(base)+'.jsonl'
            full=base+'/../../sessions/'+tname if '../..' not in base else base+'/'+tname
            try:
                t=open(full).read().replace('\\n','\n'); Gg={}
                for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\)',t):
                    k,h,w=m[1],int(m[2]),int(m[3])
                    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
                    if k not in Gg and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
                        Gg[k]=[[int(x) for x in r] for r in rows]
                out.update(Gg)
            except Exception as e:
                print(e,full)
    return out
G=load(); print(sorted(G), {k:(len(v),len(v[0])) for k,v in G.items()})
